    {
        $parser = new MySqlParser();
        $schemaParser = new MySqlSchemaParser($parser);
        $definition = $schemaParser->parse('CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255))');
        if ($definition === null) {
